// patterns.js — reference kolams for learn mode, each paired with its own
// beginner vocal lesson (in the order Carnatic students learn them).
//
// ⚠ Patterns 1–3 are PLACEHOLDER KOLAMS: valid single-line (sikku) 5×5 patterns with 4-way
// symmetry, generated by tools/find-defaults.mjs. Swap in documented
// traditional patterns from your research before presenting.
// ⚠ Verify the varisai with a teacher or source before presenting.
//
// Kolam format: crossing "x,y" → 1 (horizontal bounce) or 2 (vertical
// bounce); unlisted crossings are ✕ (the line passes straight through).
// Swara degrees: 0 Sa · 1 Ri · 2 Ga · 3 Ma · 4 Pa · 5 Da · 6 Ni · 7 Ṡa (upper)
// Each phrase is a list of [degree, beats]; the last note is held so the
// kolam ends on a long, settled Sa.

const n = (...degs) => degs.map(d => [d, 1]);
const end = (...degs) => [...n(...degs.slice(0, -1)), [degs[degs.length - 1], 3]];

