// Split the main pen's segments across a lesson's phrases, in proportion to
// each phrase's length (at least 2 segments each), summing exactly to total.
export function planSections(phrases, total, segments = null) {
  if (segments) return phrases.map((phrase, i) => ({ phrase, segs: segments[i] }));
  const beats = phrases.map(p => p.reduce((a, [, b]) => a + b, 0));
  const sum = beats.reduce((a, b) => a + b, 0);
  const segs = beats.map(b => Math.max(2, Math.round((b / sum) * total)));
  let diff = total - segs.reduce((a, b) => a + b, 0);
  for (let i = segs.length - 1; diff !== 0; i = (i - 1 + segs.length) % segs.length) {
    if (diff > 0) { segs[i]++; diff--; }
    else if (segs[i] > 2) { segs[i]--; diff++; }
  }
  return phrases.map((phrase, i) => ({ phrase, segs: segs[i] }));
}
